C:\Users\lcvle\AppData\Local\Microsoft\WindowsApps\Microsoft.PowerShell_8wekyb3d8bbwe\pwsh.exe -Command $ErrorActionPreference = 'Stop'
$PSNativeCommandUseErrorActionPreference = $true
foreach ($gitVariable in 'GIT_DIR','GIT_WORK_TREE','GIT_COMMON_DIR') { Remove-Item -LiteralPath "Env:$gitVariable" -ErrorAction SilentlyContinue }
$diagnosticTemp = (Resolve-Path -LiteralPath 'temp').Path
$env:TEMP = $diagnosticTemp
$env:TMP = $diagnosticTemp
$env:TMPDIR = $diagnosticTemp
$env:GH_PROMPT_DISABLED = '1'
$hookRoot = git rev-parse --path-format=absolute --git-path hooks
$commonRoot = git rev-parse --path-format=absolute --git-common-dir
"Hooks=$hookRoot"
"CommonGitDir=$commonRoot"
git config --get-regexp '^(core\.(hookspath|autocrlf)|gpg\.(format|ssh\.program|ssh\.allowedSignersFile))$'
foreach ($hookName in 'prepare-commit-msg','commit-msg','post-commit','post-rewrite','pre-push') {
    $hookPath = Join-Path $hookRoot $hookName
    if (Test-Path -LiteralPath $hookPath -PathType Leaf) {
        $hookLine = Select-String -LiteralPath $hookPath -SimpleMatch 'entire hooks' | Select-Object -First 1
        [pscustomobject]@{Name=$hookName; Present=$true; Entire=[bool]$hookLine}
    } else {
        [pscustomobject]@{Name=$hookName; Present=$false; Entire=$false}
    }
}
$codexHooks = Get-Content -LiteralPath '.codex/hooks.json' -Raw | ConvertFrom-Json -AsHashtable
foreach ($eventName in $codexHooks.hooks.Keys) {
    [pscustomobject]@{Event=$eventName; Entire=[bool]($codexHooks.hooks[$eventName].hooks.command -match 'entire')}
}
Get-ChildItem -LiteralPath 'temp' -Force | Select-Object Name,Attributes

