    } elseif ($itemOutput.Length -gt 10000) {
        [pscustomobject]@{ErrorKind=$null; PathMatches=[regex]::Matches($itemOutput,'(?i)(?:[A-Z]:[/\\]Users[/\\])').Count; UserInstructionMatches=[regex]::Matches($itemOutput,'Master Engineering|Operator Master Directive|APPLE_PRIVATE_KEY|support ticket').Count}
    }
}
$recentEvents | ConvertTo-Json -Compress
git status --short --branch

