$PSNativeCommandUseErrorActionPreference = $true
foreach ($gitVariable in 'GIT_DIR','GIT_WORK_TREE','GIT_COMMON_DIR') { Remove-Item -LiteralPath "Env:$gitVariable" -ErrorAction SilentlyContinue }
$diagnosticTemp = (Resolve-Path -LiteralPath 'temp').Path
$env:TEMP = $diagnosticTemp
$env:TMP = $diagnosticTemp
$env:TMPDIR = $diagnosticTemp
$env:GH_PROMPT_DISABLED = '1'
$events = foreach ($line in Get-Content -LiteralPath 'temp/implementation-retry-events.jsonl') {
    try { ConvertFrom-Json -InputObject $line } catch { continue }
}
$events | Select-Object -Last 20 | ForEach-Object {
    $record = $_
    $outcome = if ($record.item.type -eq 'command_execution') {
        if ($record.item.aggregated_output.Length -lt 2000) { $record.item.aggregated_output }
    } elseif ($record.item.type -eq 'agent_message') { $record.item.text }
    [pscustomobject]@{Type=$record.type; Item=$record.item.type; Status=$record.item.status; Exit=$record.item.exit_code; Output=$outcome}
} | ConvertTo-Json -Compress
